const themePreference=(()=>{try{return localStorage.getItem('finn-theme');}catch{return null;}})();
const applyTheme=theme=>{document.documentElement.dataset.theme=theme;const label=document.getElementById('theme-label');if(label)label.textContent=theme==='dark'?'Light mode':'Dark mode';};
applyTheme(themePreference||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'));
let companyDirectory=[];
fetch('/companies.json').then(r=>{if(!r.ok)throw Error('directory');return r.json();}).then(d=>{companyDirectory=d.companies;}).catch(()=>{});
function companyMatches(query){const q=query.trim().toLowerCase();return q.length<2?[]:companyDirectory.filter(c=>[c.name,c.nse,c.bse,...c.aliases].some(v=>v?.toLowerCase().includes(q))).sort((a,b)=>Number(b.nse?.toLowerCase()===q)-Number(a.nse?.toLowerCase()===q)).slice(0,12);}
function companyOptions(query){return companyMatches(query).map(c=>`<option value="${esc(c.name+' ('+(c.nse||c.bse)+')')}">${esc([c.nse?'NSE '+c.nse:'',c.bse?'BSE '+c.bse:''].filter(Boolean).join(' · '))}</option>`).join('');}
function researchSymbol(value){const q=value.trim().toLowerCase();const exact=companyDirectory.find(c=>[c.name,c.nse,c.bse,c.name+' ('+(c.nse||c.bse)+')',...c.aliases].some(v=>v?.toLowerCase()===q));const matches=companyMatches(value);const c=exact||(matches.length===1?matches[0]:null);if(c&&!c.nse)throw Error('This BSE-only company is listed in search, but the current research backend requires an NSE listing.');return c?.nse||value.trim();}
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const human=value=>String(value??'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const number=(value,options={})=>value===null||value===undefined||!Number.isFinite(Number(value))?'—':new Intl.NumberFormat('en-IN',{maximumFractionDigits:2,...options}).format(Number(value));
const money=value=>value===null||value===undefined?'—':number(value,{style:'currency',currency:'INR',minimumFractionDigits:2});
const compact=value=>number(value,{notation:'compact',maximumFractionDigits:1});
const when=(value,full=false)=>!value||!Number.isFinite(+new Date(value))?'Not yet':new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',...(full?{hour:'numeric',minute:'2-digit'}:{}),timeZone:'Asia/Kolkata'}).format(new Date(value));
const percent=value=>value===null||value===undefined?'—':`${Number(value)>=0?'+':''}${number(value,{minimumFractionDigits:2})}%`;
const sign=value=>value===null||value===undefined?'muted':Number(value)>=0?'positive':'negative';
const url=value=>{try{const u=new URL(value);return u.protocol==='https:'?u.href:null;}catch{return null;}};
const sourceLink=(href,label='Open source ↗')=>url(href)?`<a class="source-link" href="${esc(url(href))}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:'';
const labels={portfolio:'Portfolio',research:'Research',digests:'Digests',alerts:'Alerts'};
const categories=['results','M&A','fund_raise','management_change','litigation','insider_trading','earnings_call','investor_meetings','credit_rating','dividend','bonus_split','capex','press_release','postal_ballot','agm_egm','pledging','annual_report','guidance','routine','unclassified'];
const topicLabels={capital_allocation:'Capital allocation',business_snapshot:'Business snapshot',financial_snapshot:'Financial snapshot',trajectory:'Trajectory',balance_sheet:'Balance sheet',cash_quality:'Cash quality',narrative_vs_numbers:'Narrative vs. numbers',guidance:'Management guidance',bull_vs_bear:'Bull & bear considerations'};
const state={authenticated:false,portfolio:null,settings:null,status:null,alerts:[],notifications:[],research:[],digests:[],digest:null,job:null,
  selectedJob:null,view:'portfolio',window:null,loading:false,loadedAt:null,error:null,tickerDraft:'',starting:false,
  draft:{symbol:'',question:'',source_policy:'primary'},pendingPaint:false,refreshing:false,selectedDigest:null};
let pollTimer,toastTimer,modalVersion=0;
let paintedKey;
const deletedResearch=new Set();
const researchMarkets=new Map();
let researchRange='3M',researchMarketTable=false,alertFilter='all';
async function loadResearchMarket(symbol){
 const old=researchMarkets.get(symbol);if(old?.loading||old&&Date.now()-old.at<300000)return;
 researchMarkets.set(symbol,{...old,loading:true,at:Date.now()});
 try{const data=await api('market',{params:{symbol}});researchMarkets.set(symbol,{data,at:Date.now()});}
 catch(error){researchMarkets.set(symbol,{error:error.message,at:Date.now()});}
 paint(true);
}

async function api(resource,{method='GET',body,params={}}={}) {
  const query=new URLSearchParams({resource,...params});
  let response;
  try{response=await fetch(`/api/app?${query}`,{method,credentials:'same-origin',signal:AbortSignal.timeout(20000),
    headers:method==='GET'?{}:{'Content-Type':'application/json','X-Finn-Client':'web'},...(method!=='GET'?{body:JSON.stringify(body??{})}:{})});}
  catch(error){throw new Error(error.name==='TimeoutError'?'The backend took too long to respond. Please try again.':'Cannot reach the backend. Check that the server is running.');}
  const data=await response.json().catch(()=>({error:'The backend returned an unreadable response.'}));
  if(!response.ok){if(response.status===401&&resource!=='session')showLogin();throw new Error(data.error||`Request failed (${response.status})`);}
  return data;
}
function toast(message,error=false){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').className=`toast${error?' error':''}`;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,error?8000:4500);}
function badge(status){const names={queued:'Queued',waiting:'In progress',running:'Running',completed:'Complete',partial:'Partial',failed:'Needs attention',awaiting_extraction:'Preparing',superseded:'Updated source'};return `<span class="badge ${esc(status)}">${esc(names[status]||human(status))}</span>`;}
function empty(title,description,action=''){return `<div class="empty"><div class="empty-icon" aria-hidden="true">⌁</div><h3>${esc(title)}</h3><p>${esc(description)}</p>${action}</div>`;}
function researchBadge(job){return job.status==='waiting'&&job.next_attempt_at?'<span class="badge waiting">Automatic retry</span>':badge(job.status);}
function showLogin(){state.authenticated=false;clearTimeout(pollTimer);$('#workspace').hidden=true;$('#auth').hidden=false;$('#auth-check').hidden=true;$('#login-form').hidden=false;if($('#modal').open)$('#modal').close();}
async function checkSession(){
  $('#auth-check').hidden=false;$('#login-form').hidden=true;$('#auth-error').hidden=true;$('#connection-retry').hidden=true;
  try{const session=await api('session');if(session.authenticated)await enterWorkspace();else showLogin();}
  catch(error){$('#auth-check').hidden=true;$('#auth-error').textContent=error.message;$('#auth-error').hidden=false;$('#connection-retry').hidden=false;}
}
async function enterWorkspace(){state.authenticated=true;$('#auth').hidden=true;$('#workspace').hidden=false;readRoute();await load();schedulePoll();}
function schedulePoll(){clearTimeout(pollTimer);if(!state.authenticated)return;pollTimer=setTimeout(async()=>{if(!document.hidden)await load();schedulePoll();},6000);}
async function load({force=false}={}) {
  if(!state.authenticated)return;if(state.loading){if(force)state.reloadNeeded=true;return;}state.loading=true;
  const selected=state.selectedJob;
  const resources=['portfolio','settings','status','alerts','notifications','research','digests','digest'];
  const requests=resources.map(resource=>api(resource,{params:resource==='digest'&&state.window?{hours:String(state.window)}:{}}));
  if(selected)requests.push(api('research',{params:{id:selected}}));
  const results=await Promise.allSettled(requests);
  if(!state.authenticated){state.loading=false;return;}
  results.forEach((result,i)=>{if(result.status==='fulfilled'){
    if(i<resources.length)state[resources[i]]=resources[i]==='research'?result.value.filter(job=>!deletedResearch.has(job.id)):result.value;
    else if(selected===state.selectedJob)state.job=result.value;
  }});
  const failures=results.filter((r,i)=>r.status==='rejected'&&(i<resources.length||selected===state.selectedJob));
  if(state.selectedDigest)state.selectedDigest=state.digests.find(d=>d.id===state.selectedDigest.id)||state.selectedDigest;
  state.error=failures.length?failures[0].reason.message:null;
  if(!failures.length)state.loadedAt=new Date();
  if(state.job?.result&&state.selectedJob===selected)loadResearchMarket(state.job.nse_symbol);
  state.loading=false;paintChrome();paint();
  if(state.reloadNeeded){state.reloadNeeded=false;queueMicrotask(()=>load({force:true}));}
}
function readRoute(){const [view,id]=location.hash.slice(1).split('/');state.view=labels[view]?view:'portfolio';const selected=state.view==='research'&&/^[a-f0-9-]{36}$/i.test(id||'')?id:null;if(selected!==state.selectedJob){state.selectedJob=selected;state.job=null;}}
function paintChrome(){
  for(const a of document.querySelectorAll('[data-nav]')){a.classList.toggle('active',a.dataset.nav===state.view);if(a.dataset.nav===state.view)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}
  $('#breadcrumb-current').textContent=labels[state.view];$('#company-count').textContent=state.portfolio?.length??'—';
  const unread=state.notifications.filter(n=>n.kind==='alert'&&!n.read_at).length;$('#unread-count').textContent=unread;$('#unread-count').hidden=!unread;
  $('#sync-label').textContent=state.loadedAt?`Synced ${when(state.loadedAt,true)} IST`:'Loading saved data…';
  const enabled=state.settings?.monitoring_enabled;$('#connection-label').textContent=state.error?'Connection interrupted':enabled?'Watcher enabled':'Monitoring paused';
  $('#connection-dot').className=`status-dot${state.error?' error':enabled?'':' off'}`;
  $('#offline-banner').hidden=!state.error;$('#offline-banner').textContent=state.error?`${state.error} Showing the last data loaded.`:'';
}
function paint(force=false){
  // Polling shouldn't rebuild unchanged buttons/forms every few seconds. Only
  // visible data changes invalidate a view; sync timestamps update separately.
  const watcher=[state.settings,state.status?.jobs,state.status?.processingErrors,state.status?.monitor];
  const digest=[state.digest?.items,state.digest?.saved_company_results];
  const key=JSON.stringify([state.view,state.view==='research'?[state.selectedJob,state.job,state.research]:
    state.view==='portfolio'?[state.portfolio,watcher,digest,state.notifications]:
    state.view==='digests'?[watcher,digest,state.window,state.selectedDigest,state.digests,Math.floor(Date.now()/60000)]:
    [state.alerts,state.notifications,watcher]]);
  if(!force&&key===paintedKey){state.pendingPaint=false;return;}
  const editing=['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName);
  if(!force&&(editing||$('#modal').open)){
    if(editing&&state.view==='research'&&$('#research-output'))$('#research-output').innerHTML=researchResult();
    state.pendingPaint=true;return;
  }
  state.pendingPaint=false;
  if(state.portfolio===null){$('#main').innerHTML=`<div class="page-loading"><span class="spinner"></span> ${state.error?'Waiting for the backend…':'Loading your workspace…'}</div>`;return;}
  $('#main').innerHTML=({portfolio:portfolioView,research:researchView,digests:digestsView,alerts:alertsView}[state.view])();paintedKey=key;
}
function heading(title,description,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${state.view==='research'?'FOLLOW YOUR CURIOSITY':'YOUR DAILY PERSPECTIVE'}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`;}
function stat(name,value,detail){return `<div class="stat corner"><div class="stat-name">${esc(name)}</div><div class="stat-value numeric">${esc(value)}</div><div class="stat-detail">${esc(detail)}</div></div>`;}
function refreshButton(){return `<button class="button secondary" data-action="settings">Watcher settings</button><button class="button primary" data-action="refresh" ${state.refreshing?'disabled':''}>${state.refreshing?'<span class="spinner"></span>':'<span aria-hidden="true">↻</span>'} Refresh updates</button>`;}
function pendingCount(){return (state.status?.jobs||[]).filter(j=>['queued','running','failed'].includes(j.status)).reduce((n,j)=>n+Number(j.count),0);}
function trackingSummary(){const s=state.settings,r=type=>s?.rules?.find(x=>x.rule_type===type);return `<section class="tracking-bar"><div><span class="tracking-indicator ${s?.monitoring_enabled?'on':''}"></span><strong>${s?.monitoring_enabled?'Tracking enabled':'Tracking paused'}</strong><p>Check every ${s?.monitoring_minutes??'—'} min · Digest every ${s?.digest_hours??'—'}h · Price ${r('price_move')?.enabled?'±'+number(r('price_move').settings.percent)+'%':'off'} · Volume ${r('volume_spike')?.enabled?number(r('volume_spike').settings.multiple)+'×':'off'} · Filings ${r('announcement')?.enabled?(r('announcement').settings.categories?.length||0)+' categories':'off'}</p></div><div><button class="button ${s?.monitoring_enabled?'secondary':'primary'}" data-action="toggle-monitor" aria-pressed="${!!s?.monitoring_enabled}">${s?.monitoring_enabled?'Pause tracking':'Enable tracking'}</button><button class="text-button" data-action="settings">Settings</button></div></section>`;}
function portfolioView(){
  const items=state.portfolio,covered=items.filter(c=>c.market).length,unread=state.notifications.filter(n=>n.kind==='alert'&&!n.read_at).length;
  return heading('Your portfolio.','The companies you follow. The changes that matter.',refreshButton())+trackingSummary()+
    `<div class="stats-grid">${stat('Companies watching',items.length,'NSE-listed equities')}${stat('Unread alerts',unread,'Your configured thresholds')}</div>
    <div class="content-grid"><div><section class="panel"><div class="panel-head"><div><h2>Your watchlist</h2><p>Prices and daily changes from completed market sessions</p></div><span class="badge">EOD</span></div>
    ${!covered&&state.status?.monitor?.last_error?`<p class="notice">Collection needs attention: ${esc(state.status.monitor.last_error)}. Check Settings → Backend activity.</p>`:''}
    <form id="add-company" class="add-company"><label for="ticker">Add a company</label><div class="input-row"><input id="ticker" name="symbol" placeholder="Company name or NSE symbol" list="portfolio-suggestions" value="${esc(state.tickerDraft)}" maxlength="40" autocomplete="off" autocapitalize="characters" required><datalist id="portfolio-suggestions">${companyOptions(state.tickerDraft)}</datalist><button class="button secondary compact" type="submit">+ Watch</button></div></form>
    ${items.length?`<div class="table-wrap"><table><thead><tr><th scope="col">COMPANY</th><th scope="col">EOD CLOSE</th><th scope="col">DAILY CHANGE</th><th scope="col">VOLUME</th><th scope="col"><span class="sr-only">Actions</span></th></tr></thead><tbody>${items.map(companyRow).join('')}</tbody></table></div>`:empty('Start with a company','Add an NSE ticker above. The watcher will collect its announcements and end-of-day data.')}
    <div class="panel-footer"><span>${items.length} compan${items.length===1?'y':'ies'} tracked</span><span>No live or intraday prices</span></div></section>
    <section class="panel"><div class="panel-head"><div><h2>What changed</h2><p>Portfolio announcements · last ${state.window||state.settings?.digest_hours||24} hours</p></div><a class="text-button" href="#digests">View digest ↗</a></div>${digestFeed(state.digest,{preview:true})}</section>
    ${savedContext()}</div><aside class="watcher-aside"><div class="accent-panel"><div class="eyebrow">BEYOND THE HEADLINES</div><h2>Ask a better<br>question.</h2><p>Dig into annual reports and earnings calls, with evidence a click away.</p><a class="text-button" href="#research">Start researching ↗</a></div></aside></div>`;
}
function companyRow(c){const m=c.market,ps=c.market_status;const priceNote=ps?.state==='failed'?'Price fetch failed · see details':ps?.state==='collecting'?'Fetching completed sessions…':m?`Session ${when(m.session_date)}`:'Waiting for collection · Refresh updates';return `<tr><td><div class="company-cell"><span class="ticker-logo" aria-hidden="true">${esc(c.nse_symbol.slice(0,2))}</span><div><button class="company-button" data-action="company" data-symbol="${esc(c.nse_symbol)}">${esc(c.nse_symbol)}</button><div class="company-name">${esc(c.name!==c.nse_symbol?c.name:'NSE · Equity')}</div></div></div></td><td class="numeric">${money(m?.close)}<div class="cell-sub">${ps?.state==='failed'?`<details><summary>${esc(priceNote)}</summary>${esc(ps.error)}</details>`:esc(priceNote)}</div></td><td class="numeric ${sign(m?.change_percent)}">${percent(m?.change_percent)}</td><td class="numeric">${compact(m?.volume)}</td><td><div class="row-actions"><button class="icon-button" title="View ${esc(c.nse_symbol)}" aria-label="View ${esc(c.nse_symbol)}" data-action="company" data-symbol="${esc(c.nse_symbol)}">↗</button><button class="icon-button" title="Stop watching ${esc(c.nse_symbol)}" aria-label="Stop watching ${esc(c.nse_symbol)}" data-action="remove" data-symbol="${esc(c.nse_symbol)}">×</button></div></td></tr>`;}
function watcherPanel(){const monitor=state.status?.monitor,s=state.settings,r=type=>s?.rules?.find(r=>r.rule_type===type),enabled=s?.monitoring_enabled;
  const running=monitor?.lease_expires_at&&+new Date(monitor.lease_expires_at)>Date.now();
  return `<section class="panel side-panel"><h2>The portfolio watcher</h2><div class="watcher-status"><span class="status-dot ${enabled?'':'off'}"></span>${enabled?'Monitoring enabled':'Monitoring paused'}</div><p class="side-note">${running?'A background step is running. You can keep using the app.':monitor?.last_finished_at?`Last step completed ${when(monitor.last_finished_at,true)} IST.`:'Waiting for the first background check.'}</p><div class="side-rule"></div><div class="step-line"><span>Check interval</span><strong>${s?.monitoring_minutes??'—'} min</strong></div><div class="step-line"><span>Digest window</span><strong>${s?.digest_hours??'—'} hours</strong></div><div class="step-line"><span>Daily price move</span><strong>${r('price_move')?.enabled?`±${number(r('price_move').settings.percent)}%`:'Off'}</strong></div><div class="step-line"><span>Volume spike</span><strong>${r('volume_spike')?.enabled?`${number(r('volume_spike').settings.multiple)}× average`:'Off'}</strong></div><div class="side-rule"></div><p class="side-note">Background updates run while the local server is open. Alerts appear in this workspace.</p><button class="button secondary" data-action="toggle-monitor">${enabled?'Pause monitoring':'Resume monitoring'}</button><button class="text-button" data-action="status" style="margin-top:16px">View processing status ↗</button></section>`;
}
function digestFeed(digest,{preview=false}={}){
  if(!digest)return empty('Loading the digest','Fetching saved announcements from the backend.');
  const main=digest.items.filter(item=>!item.developments?.length||!item.developments.every(d=>d.importance==='routine'));
  const routine=digest.items.filter(item=>item.developments?.length&&item.developments.every(d=>d.importance==='routine'));
  const shown=preview?main.slice(0,4):main;
  return `${digest.items.length?`<div class="feed-list">${shown.map(disclosureCard).join('')}</div>`:empty('No filings saved in this window','Try another time window, or check backend activity in Settings.')}
    ${preview&&main.length>4?`<div class="panel-footer"><a class="text-button" href="#digests">View all ${main.length} developments ↗</a></div>`:''}
    ${routine.length?`<details class="routine"><summary>${routine.length} routine announcement${routine.length===1?'':'s'}</summary><div>${routine.map(disclosureCard).join('')}</div></details>`:''}`;
}
function disclosureCard(item){return `<article class="feed-item"><div class="feed-meta"><strong>${esc(item.company)}</strong><span>${when(item.published_at,true)} IST</span>${badge(item.processing_status)}</div>
  ${item.analysis?.coverage?.analysed_all_prepared_pages===false?`<p class="help">Selected evidence · ${item.analysis.coverage.selected_pages} of ${item.analysis.coverage.indexed_pages} indexed pages reviewed. Full filing linked below.</p>`:''}${item.analysis?.available&&!item.analysis.is_current?'<div class="notice">Previously saved analysis. The updated source is awaiting analysis.</div>':''}
  ${item.developments?.length?item.developments.map((d,index)=>`<div><h3>${esc(d.headline)}</h3><p>${esc(d.summary)}</p>${d.importance==='high'?'<span class="badge high">Priority</span>':''} <button class="text-button" data-action="digest-evidence" data-disclosure="${esc(item.id)}" data-index="${index}">View evidence</button></div>`).join(''):`<h3>${esc(item.title)}</h3><p>${item.processing_status==='failed'?'Analysis is paused. Check processing status for the error and retry timing.':'This filing is saved; its analysis is not ready yet.'}</p>`}
  <div class="source-row" style="margin-top:11px">${sourceLink(item.source_url,'Original filing ↗')}<span class="muted small">${item.analysis?.analysed_at?`Analysed ${when(item.analysis.analysed_at,true)} IST`:''}</span></div></article>`;}
function savedContext(){const rows=state.digest?.saved_company_results||[];if(!rows.length)return '';return `<section class="panel"><div class="panel-head"><div><h2>Last saved analysis</h2><p>Company context · may fall outside the selected digest window</p></div></div><div class="feed-list">${rows.map(r=>`<article class="feed-item"><div class="feed-meta"><strong>${esc(r.company)}</strong><span>Analysed ${when(r.analysed_at,true)} IST</span>${!r.input_is_current?'<span class="badge partial">Updated source pending</span>':''}</div><h3>${esc(r.title)}</h3><p>${esc(r.result?.developments?.[0]?.summary||'Source analysis is saved.')}</p><div class="source-row">${sourceLink(r.source_url)}<span class="muted small">Published ${when(r.published_at)}${r.pending_disclosures?` · ${r.pending_disclosures} other disclosures pending`:''}</span></div></article>`).join('')}</div></section>`;}
function digestsView(){const current=state.selectedDigest?.result||state.digest;
 const windows=[...new Set([12,24,36,48,72,168,state.settings?.digest_hours,state.window].filter(Number.isFinite))].sort((a,b)=>a-b);
 const items=current?.items||[],pending=items.filter(i=>i.processing_status!=='completed').length;
 return heading('Your digest.','Important company updates, collected in one place.',`<button class="button secondary" data-action="settings">Digest settings</button><button class="button primary" data-action="generate-digest">Generate digest now</button>`)+
 `<section class="panel"><div class="panel-head"><div><h2>${state.selectedDigest?'Saved digest':'Latest window'}</h2><p>${current?`${when(current.from,true)} — ${when(current.to,true)} IST`:''}</p></div><label class="window-control" for="digest-window">Window<select id="digest-window">${windows.map(hours=>`<option value="${hours}" ${(state.window||state.settings?.digest_hours||24)===hours?'selected':''}>${hours}h</option>`).join('')}</select></label></div><div class="digest-summary"><span>${items.length} filing${items.length===1?'':'s'}</span><span>${pending?pending+' awaiting analysis':items.length?'Analysis ready':'No filings in this window'}</span><span>Scheduled every ${state.settings?.digest_hours||24}h</span>${state.selectedDigest?'<button class="text-button" data-action="current-digest">← Current window</button>':''}</div>${digestOverview(current)}${digestFeed(current)}</section>
 <details class="digest-archive"><summary>Past digests <span>${state.digests.length}</span></summary>${state.digests.length?state.digests.map(d=>`<button class="digest-archive-item" data-action="saved-digest" data-id="${esc(d.id)}"><span><strong>${when(d.window_start,true)} — ${when(d.window_end,true)}</strong><small>${number(d.result?.disclosure_count||0)} filing${d.result?.disclosure_count===1?'':'s'} · ${d.result?.items?.filter(i=>i.processing_status!=='completed').length||0} awaiting analysis</small></span><span aria-hidden="true">↗</span></button>`).join(''):'<p class="help">Generate a digest now, or let the watcher save the initial snapshot.</p>'}</details>`;
}
function digestOverview(data){
 if(!data)return '';const c=data.coverage,rows=data.latest_market_snapshot||[],symbols=[...new Set(rows.map(r=>r.nse_symbol))].sort();
 const alerts=data.alerts_created_in_window||[];
 return `${c?`<div class="digest-summary"><span>${c.companies} companies tracked</span><span>${c.companies_with_prices} with saved prices</span><span>${c.companies_checked} sources checked since window start</span></div>${c.pending_companies||c.collection_errors?.length?`<p class="notice">Collection is incomplete for ${c.pending_companies} companies${c.collection_errors?.length?`; ${c.collection_errors.length} source errors`:''}. This digest will fill in as collection and analysis finish. An empty filing list does not confirm there were no announcements.</p>`:''}`:''}
 <details class="routine"><summary>Market snapshot · ${symbols.length} companies</summary><p class="help">${esc(data.market_snapshot_note||'Latest saved completed sessions, not live prices.')}</p>${symbols.length?`<div class="table-wrap"><table><thead><tr><th>Company</th><th>Close</th><th>Volume</th><th>Session</th></tr></thead><tbody>${symbols.map(symbol=>{const close=rows.find(r=>r.nse_symbol===symbol&&r.metric==='close'),volume=rows.find(r=>r.nse_symbol===symbol&&r.metric==='volume');return `<tr><td>${esc(symbol)}</td><td>${money(close?.value)}</td><td>${compact(volume?.value)}</td><td>${when(close?.session_date)}</td></tr>`;}).join('')}</tbody></table></div>`:'<p class="help">Waiting for completed-session prices.</p>'}</details>
 <details class="routine"><summary>Alerts raised in this window · ${alerts.length}</summary>${alerts.length?alerts.map(a=>`<article class="feed-item"><strong>${esc(a.nse_symbol)}</strong><p>${esc(a.message)}</p><span class="help">${when(a.created_at,true)} IST</span></article>`).join(''):'<p class="help">No saved alerts in this window. Alerts require successfully collected data and a configured threshold being crossed; company alerts also require completed analysis.</p>'}</details>`;
}
function alertsView(){const alerts=state.alerts.filter(a=>alertFilter==='all'||alertFilter==='market'&&a.trigger_details?.metric||alertFilter==='company'&&!a.trigger_details?.metric||alertFilter==='unread'&&state.notifications.some(n=>n.kind==='alert'&&n.reference_id===a.id&&!n.read_at));return heading('Your attention, well spent.','Company developments and market moves worth a closer look.',`<button class="button secondary" data-action="settings">Configure alerts</button>`)+
  `<div class="alert-filters" aria-label="Filter alerts">${[['all','All alerts'],['unread','Unread'],['company','Company'],['market','Market']].map(([value,label])=>`<button class="button secondary compact" data-action="alert-filter" data-filter="${value}" aria-pressed="${alertFilter===value}">${label}</button>`).join('')}</div><div class="content-grid"><div>${alerts.length?alerts.map(a=>{const notification=state.notifications.find(n=>n.kind==='alert'&&n.reference_id===a.id);const details=a.trigger_details||{};return `<article class="alert-card"><div class="feed-meta"><strong>${esc(a.nse_symbol)}</strong><span>${when(a.created_at,true)} IST</span><span class="badge high">${details.metric?'Market activity':'Announcement'}</span>${notification&&!notification.read_at?'<span class="badge">Unread</span>':''}</div><h3>${esc(details.headline||a.message)}</h3>${details.headline?`<p>${esc(a.message)}</p>`:''}<p>${esc(details.why_it_matters||'A configured monitoring threshold was crossed.')}</p>${details.session?`<p class="small">Market session ${when(details.session)} · threshold ${number(details.threshold)}${details.metric==='close'?'%':'×'}</p>`:''}<div class="alert-footer"><div class="source-row">${sourceLink(details.source_url||details.evidence?.[0]?.source_url)}<button class="text-button" data-action="company" data-symbol="${esc(a.nse_symbol)}">Company details ↗</button></div>${notification&&!notification.read_at?`<button class="button secondary compact" data-action="read-notification" data-id="${esc(notification.id)}">Mark read</button>`:''}</div></article>`;}).join(''):`<section class="panel">${empty('All clear here',alertFilter==='all'?'Important updates will appear here when your thresholds are crossed.':'No alerts match this filter.')}</section>`}</div><aside class="watcher-aside"></aside></div>`;}
function researchHistory(){return state.research.length?state.research.map(job=>`<div class="job-history-row"><button class="job-item ${job.id===state.selectedJob?'selected':''}" data-action="research-job" data-id="${esc(job.id)}"><span class="feed-meta"><strong>${esc(job.nse_symbol)}</strong>${researchBadge(job)}</span><span class="job-question">${esc(job.question)}</span><span class="cell-sub">${when(job.created_at,true)} IST</span></button><button class="job-delete" data-action="delete-research" data-id="${esc(job.id)}" aria-label="Delete research for ${esc(job.nse_symbol)}, started ${esc(when(job.created_at,true))} IST">Delete</button></div>`).join(''):empty('Your research library','Completed and ongoing briefs will be saved here.');}
function researchView(){const draft=state.draft;return heading('A company. A clearer picture.','Explore the business behind the ticker.')+
 `<section class="research-search panel"><form id="research-form"><label for="research-symbol">Find a company</label><div class="search-line"><span aria-hidden="true">⌕</span><input id="research-symbol" name="symbol" list="company-suggestions" value="${esc(draft.symbol)}" placeholder="Company name, NSE symbol or BSE code" autocomplete="off" required><datalist id="company-suggestions">${companyOptions(draft.symbol)}</datalist><button class="button primary" type="submit" ${state.starting?'disabled':''}>${state.starting?'Starting…':'Research ↗'}</button></div><details class="advanced-options"><summary>Advanced options</summary><label for="research-question">Focus or follow-up question</label><textarea id="research-question" name="question" maxlength="2000" placeholder="Leave blank for a broad overview">${esc(draft.question)}</textarea><label for="source-policy">Sources</label><select id="source-policy" name="source_policy"><option value="primary" ${draft.source_policy!=='assignment'?'selected':''}>Company primary disclosures</option><option value="assignment" ${draft.source_policy==='assignment'?'selected':''}>Annual reports + transcripts only</option></select><p class="help">Search covers the available NSE/BSE equity catalogue. Research currently supports NSE listings; dual-listed companies use their NSE ticker.</p></details></form></section>
 <div class="research-workspace"><aside class="research-history"><div class="panel-head"><h2>Recent research</h2><span class="badge">${state.research.length}</span></div>${researchHistory()}</aside><div id="research-output">${researchResult()}</div></div>`;}
function researchMarket(job){
 const tracked=state.portfolio?.some(c=>c.nse_symbol===job.nse_symbol),entry=researchMarkets.get(job.nse_symbol),data=entry?.data;
 const add=`<button class="button ${tracked?'secondary':'primary'} compact" data-action="research-add-portfolio" data-symbol="${esc(job.nse_symbol)}" ${tracked?'disabled':''}>${tracked?'In your portfolio ✓':'Add to portfolio +'}</button>`;
 const head=`<div class="exhibit-heading"><div><div class="eyebrow">MARKET PERSPECTIVE</div><h3>${esc(job.nse_symbol)} · completed EOD</h3></div>${add}</div>`;
 if(!data?.rows?.length)return `<section class="research-market">${head}<p>${esc(entry?.error||'Loading market history independently of document analysis…')}</p>${entry?.error?`<button class="text-button" data-action="market-retry" data-symbol="${esc(job.nse_symbol)}">Retry market data</button>`:''}</section>`;
 const all=data.rows,last=all.at(-1),prior=all.at(-2),cutoff=new Date(last.day+'T00:00:00Z');cutoff.setUTCMonth(cutoff.getUTCMonth()-({ '1M':1,'3M':3,'6M':6,'1Y':12}[researchRange]||3));
 const rows=all.filter(r=>r.day>=cutoff.toISOString().slice(0,10)),first=rows[0],change=prior?(last.values.close/prior.values.close-1)*100:null;
 const average=all.slice(-21,-1),avg=average.length?average.reduce((n,r)=>n+r.values.volume,0)/average.length:null;
 const rangeReturn=first&&first.values.close>0?(last.values.close/first.values.close-1)*100:null;
 const highs=rows.map(r=>r.values.high),lows=rows.map(r=>r.values.low),prices=rows.map(r=>r.values.close),min=Math.min(...prices),max=Math.max(...prices),span=max-min||1,maxVolume=Math.max(1,...rows.map(r=>r.values.volume));
 const points=rows.map((r,i)=>`${20+i/Math.max(1,rows.length-1)*540},${150-(r.values.close-min)/span*125}`).join(' ');
 const chart=`<svg class="chart market-chart" viewBox="0 0 580 240" role="img" aria-label="Completed daily closing prices with aligned daily volume bars"><path d="M20 160H560M20 230H560" stroke="#dce3d5"/><polyline points="${points}" fill="none" stroke="#315c43" stroke-width="2.5"/>${rows.map((r,i)=>`<rect x="${18+i/Math.max(1,rows.length-1)*540}" y="${230-r.values.volume/maxVolume*50}" width="${Math.max(1,Math.min(8,500/rows.length))}" height="${r.values.volume/maxVolume*50}" fill="#a4b98b"><title>${esc(r.day)} · Volume ${number(r.values.volume)}</title></rect>`).join('')}${rows.map((r,i)=>`<circle cx="${20+i/Math.max(1,rows.length-1)*540}" cy="${150-(r.values.close-min)/span*125}" r="5" fill="transparent" stroke="transparent" tabindex="0" role="button" data-action="market-point" data-index="${all.indexOf(r)}" aria-label="${esc(r.day)}, close ${esc(money(r.values.close))}, volume ${number(r.values.volume)}"><title>${esc(r.day)} · ${money(r.values.close)} · Volume ${number(r.values.volume)}</title></circle>`).join('')}<text x="20" y="15" font-size="11">${esc(money(max))}</text><text x="20" y="170" font-size="10">${esc(money(min))} · Volume below</text></svg>`;
 const table=`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Close</th><th>High / low</th><th>Volume</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.day)}</td><td>${money(r.values.close)}</td><td>${money(r.values.high)} / ${money(r.values.low)}</td><td>${number(r.values.volume)}</td></tr>`).join('')}</tbody></table></div>`;
 return `<section class="research-market">${head}<div class="market-tiles"><div><small>Last completed close</small><strong>${money(last.values.close)}</strong><span class="${sign(change)}">${percent(change)} vs prior session</span></div><div><small>Daily volume</small><strong>${compact(last.values.volume)}</strong><span>${avg>0?number(last.values.volume/avg)+'× prior '+average.length+'-session average':'Insufficient volume history'}</span></div><div><small>Selected-period price return</small><strong>${percent(rangeReturn)}</strong><span>High ${money(Math.max(...highs))} · Low ${money(Math.min(...lows))}</span></div></div><div class="market-controls">${['1M','3M','6M','1Y'].filter(range=>{const months={'1M':1,'3M':3,'6M':6,'1Y':12}[range];const boundary=new Date(last.day+'T00:00:00Z');boundary.setUTCMonth(boundary.getUTCMonth()-months);return Date.parse(all[0].day)<=+boundary+3*86400000;}).map(range=>`<button class="button secondary compact" data-action="market-range" data-range="${range}" aria-pressed="${range===researchRange}">${range}</button>`).join('')}<button class="text-button" data-action="market-table">${researchMarketTable?'Show chart':'Show table'}</button></div>${researchMarketTable?table:chart}<p id="market-point-detail" class="help" aria-live="polite">${esc(last.day)} · Close ${money(last.values.close)} · Volume ${number(last.values.volume)}</p>${!researchMarketTable?`<label for="market-session">Inspect a session</label><select id="market-session">${rows.map(r=>`<option value="${all.indexOf(r)}" ${r===last?'selected':''}>${esc(r.day)} · ${money(r.values.close)} · ${number(r.values.volume)} shares</option>`).join('')}</select>`:''}<p class="help">Available selection: ${esc(first.day)} → ${esc(last.day)} (${rows.length} sessions). Raw close price return excludes dividends and can be distorted by splits; it is not adjusted total return. Session ${esc(last.day)} · fetched ${when(data.fetched_at,true)} IST. ${sourceLink(data.source_url,'Yahoo Finance source ↗')}${data.stale?' · Cached data: refresh failed.':''}</p></section>`;
}
function observationButton(o){return `<button class="text-button" data-action="observation" data-index="${state.job.result.exhibits.observations.findIndex(v=>v.metric===o.metric&&v.value===o.value&&v.scope===o.scope&&v.unit===o.unit&&v.period_start===o.period_start&&v.period_end===o.period_end&&v.label===o.label)}">${number(o.value)} ${esc(o.unit)} ↗</button>`;}
function researchExhibits(result){
 const x=result.exhibits;if(!x?.observations?.length)return '';
 const rows=x.observations;
 const table=`<div class="table-wrap"><table><thead><tr><th>Measure</th><th>Period</th><th>Scope</th><th>Value / source</th></tr></thead><tbody>${rows.map(o=>`<tr><td>${esc(o.label||human(o.metric))}</td><td>${esc(o.period_start)} → ${esc(o.period_end)}</td><td>${esc(o.scope)}</td><td>${observationButton(o)}</td></tr>`).join('')}</tbody></table></div>`;
 const groups=new Map();for(const o of rows){const key=[o.metric,o.scope,o.unit,o.metric.includes('revenue')&&o.metric!=='revenue'?o.period_end:''].join('|');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(o);}
 const charts=[...groups.values()].map(group=>{const max=Math.max(1,...group.map(o=>Math.abs(o.value)));return `<div class="exhibit"><h4>${esc(human(group[0].metric))} <small>${esc(group[0].scope)} · ${esc(group[0].unit)}</small></h4>${group.map(o=>`<div class="exhibit-row"><span>${esc(o.label||o.period_end)}<small>${esc(o.period_start)} → ${esc(o.period_end)}</small></span><div><div class="exhibit-track"><span style="width:${Math.abs(o.value)/max*100}%;background:${o.value<0?'#b64c48':'#517858'}"></span></div>${observationButton(o)}</div></div>`).join('')}</div>`;}).join('');
 return `<section id="research-financials" class="report-section"><div class="exhibit-heading"><h3>Financial evidence</h3><button class="button secondary compact" data-action="exhibit-toggle">Chart / table</button></div><div id="research-charts">${charts}</div><div id="research-table" hidden>${table}</div>${x.comparisons.map(c=>`<p><strong>${esc(human(c.metric))}: ${number(c.change)}${c.metric==='operating_margin'?' percentage points':'%'}</strong> · ${esc(c.prior.period_end)} → ${esc(c.current.period_end)}. <span class="help">Calculated: ${esc(c.method)}.</span></p>`).join('')}${x.divergence?.map(d=>`<p class="notice neutral">Revenue changed ${number(d.revenue.change)}% while PAT changed ${number(d.profit.change)}% over the same comparable periods. ${d.revenue.change>d.profit.change?'Profit growth lagged revenue growth.':'Profit growth exceeded or matched revenue growth.'} The figures establish the difference; its causes require the cited operating and margin evidence.</p>`).join('')||''}${x.cash.length?`<h3>Do profits turn into cash?</h3>${x.cash.map(c=>`<p>${esc(c.profit.period_start)} → ${esc(c.profit.period_end)} · ${esc(c.profit.scope)}<br>PAT ${observationButton(c.profit)} · Net operating cash ${observationButton(c.cash)}<span class="exhibit-track"><span style="width:${Math.abs(c.profit.value)/Math.max(1,Math.abs(c.profit.value),Math.abs(c.cash.value))*100}%;background:#517858"></span></span><span class="exhibit-track"><span style="width:${Math.abs(c.cash.value)/Math.max(1,Math.abs(c.profit.value),Math.abs(c.cash.value))*100}%;background:${c.cash.value<0?'#b64c48':'#8da86e'}"></span></span>${c.conversion!==null?` · ${number(c.conversion)}× cash conversion`:''}<br><span class="help">${esc(c.method)}. Timing, tax and working-capital movements can affect this relationship; see the supporting analysis.</span></p>`).join('')}`:'<p class="help">Cash conversion is unavailable without matched PAT and net operating cash periods, units and scope.</p>'}${x.delivery?.length?`<h3>Promises versus reported outcomes</h3><div class="table-wrap"><table><thead><tr><th>Dated commitment</th><th>Target period / scope</th><th>Outcome</th></tr></thead><tbody>${x.delivery.map(d=>`<tr><td>${esc(d.target.published_at)}<br>${esc(d.target.quote)}<br>${sourceLink(d.target.source_url,'Management source ↗')}</td><td>${esc(d.target.period_start)} → ${esc(d.target.period_end)}<br>${esc(d.target.scope)} · ${esc(d.target.unit)}</td><td>${d.outcome?observationButton(d.outcome):'No matched reported observation'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="help">Promises versus delivery: no fully dated numerical commitment and compatible outcome have been established.</p>'}${x.conflicts?'<p class="notice">Conflicting observations were excluded from exhibits.</p>':''}</section>`;
}
function researchMetricSummary(result){const observations=result.exhibits?.observations||[];const latest=['revenue','pat','operating_margin','net_operating_cash','capex'].map(metric=>observations.filter(o=>o.metric===metric).sort((a,b)=>b.period_end.localeCompare(a.period_end))[0]).filter(Boolean);return latest.length?`<div class="overview-metrics">${latest.map(o=>`<div><span class="section-label">${esc(human(o.metric))}</span><strong>${observationButton(o)}</strong><small>${esc(o.period_start)} → ${esc(o.period_end)} · ${esc(o.scope)}</small></div>`).join('')}</div>`:'';}
function researchTakeaway(result){
 const all=result.sections.flatMap(s=>s.findings.map(f=>({...f,topic:s.topic})));
 const chosen=[];for(const topic of ['business_snapshot','financial_snapshot','trajectory','balance_sheet','cash_quality','narrative_vs_numbers','guidance','capital_allocation']){const f=all.find(f=>f.topic===topic);if(f)chosen.push(f);}
 const cite=f=>f.evidence_indexes.map(index=>`<button class="citation-button" data-action="research-evidence" data-index="${index}">[${index+1}]</button>`).join('');
 const concern=all.find(f=>f.topic==='bull_vs_bear'||f.topic==='balance_sheet');
 return `<section class="research-takeaway"><div class="eyebrow">RESEARCH OVERVIEW</div>${researchMetricSummary(result)}${chosen.map(f=>`<div class="takeaway-item"><span class="takeaway-marker">${String(chosen.indexOf(f)+1).padStart(2,'0')}</span><div><span class="section-label">${esc(topicLabels[f.topic]||human(f.topic))}</span><p>${esc(f.statement.length>220?f.statement.slice(0,217)+'…':f.statement)} ${cite(f)}</p></div></div>`).join('')}${concern?`<details><summary>Risk and balance-sheet context</summary><p>${esc(concern.statement)} ${cite(concern)}</p></details>`:''}${result.adaptive?.unresolved_questions?.[0]?`<p class="takeaway-question"><strong>Still to establish</strong><br>${esc(result.adaptive.unresolved_questions[0].question)} <button class="text-button" data-action="research-followup" data-index="0">Investigate ↗</button></p>`:''}</section>`;
}
function researchSections(result){return `<div class="analysis-grid">${result.sections.filter(s=>s.findings?.length).map(section=>`<section class="analysis-card"><div class="section-label">${esc(topicLabels[section.topic]||human(section.topic))}</div>${section.findings.map((f,i)=>`<div class="analysis-finding"><span class="finding-number">${String(i+1).padStart(2,'0')}</span><p>${esc(f.statement)} ${f.evidence_indexes.map(index=>`<button class="citation-button" data-action="research-evidence" data-index="${Number(index)}" aria-label="Open evidence ${index+1}">[${index+1}]</button>`).join('')}</p></div>`).join('')}</section>`).join('')}</div>`;}
function researchResult(){const job=state.job;
  if(state.starting)return `<section class="panel research-loading" role="status"><div class="loading-orb" aria-hidden="true">✧</div><h2>Opening your research</h2><p>Finding primary sources for your company.</p><div class="skeleton-preview" aria-hidden="true"><span></span><span></span><span></span></div></section>`;
  if(!state.selectedJob)return `<section class="panel">${empty('A clearer view starts with a question.','Choose a company and ask about its growth, financial health, management guidance, or the case on either side.')}<div class="panel-body"><div class="side-rule"></div><p class="muted small">Primary company sources only. No broker notes, news summaries, or company facts from model memory.</p></div></section>`;
  if(!job)return `<section class="panel"><div class="page-loading"><span class="spinner"></span> Loading research…</div></section>`;
  const quotaPaused=job.error_kind==='quota_limit';
  const retryAt=job.research_state?.quota_retry_at;
  const quotaMessage=quotaPaused?(retryAt?`Model request limit reached. Please retry after ${when(retryAt,true)} IST. Your saved progress is retained.`:'Model request limit reached. Please retry when your quota becomes available. Your saved progress is retained.'):'';
  const unavailable=job.result?.report_type==='source_excerpts';
  const result=unavailable?null:job.result;
  const refining=!!result&&['running','waiting','queued'].includes(job.status);
  const focused=job.options?.mode==='focused'||(job.options?.mode!=='full'&&(job.research_state?.mode||result?.coverage));
  const docs=job.documents?.map(d=>({...d,selected_pages:job.research_state?.coverage?.find(c=>c.document_id===d.id)?.selected_pages}));
  const header=`<div class="report-header"><div class="feed-meta"><strong>${esc(job.nse_symbol)}</strong>${researchBadge(job)}<span>Started ${when(job.created_at,true)} IST</span><button class="text-button negative" data-action="delete-research" data-id="${esc(job.id)}">Delete research</button></div><h2>${esc(result?.title||job.question)}</h2><p>${result?`${quotaPaused?'Saved brief · model request limit reached':refining?'Initial brief saved · additional evidence is being checked':'Completed '+when(job.completed_at,true)+' IST'} · ${job.data_as_of?.pages??'—'} pages with selected evidence`:'Your question is being checked against the company’s primary documents.'}</p></div>`;
  if(result){return `<section class="panel">${header}${researchMarket(job)}<div class="report-body">${quotaPaused?`<p class="notice">${esc(quotaMessage)}</p><button class="button secondary" data-action="retry-research" data-id="${esc(job.id)}">Retry research</button>`:''}${job.status==='partial'?`<div class="notice">${['source_findings','source_excerpts'].includes(result.report_type)?'The model could not complete a validated brief. Saved source evidence is shown below.':'Some evidence could not be used. See the coverage limitations below.'}</div>`:''}
    ${refining?'<p class="notice">Your initial brief is ready. Targeted research continues in the background.</p>':''}
    ${researchTakeaway(result)}${researchExhibits(result)}${researchSections(result)}
    ${result.missing_topics?.length?`<div class="notice neutral">Not covered: ${result.missing_topics.map(t=>esc(topicLabels[t]||human(t))).join(', ')}.</div>`:''}
    ${result.source_issues?.length?`<details class="routine"><summary>${result.source_issues.length} supplementary or source preparation issues</summary><ul>${result.source_issues.map(s=>`<li>${esc(s.title)} · ${esc(s.status)}: ${esc(s.reason)}</li>`).join('')}</ul></details>`:''}
    ${result.limitations?.length?`<section class="report-section"><h3>Coverage & limitations</h3><ul class="report-limitations">${result.limitations.map(l=>`<li>${esc(l)}</li>`).join('')}</ul></section>`:''}
    <details class="routine"><summary>Sources & coverage</summary>    ${result.adaptive?`<p class="help">${result.adaptive.passes} evidence pass(es) · ${result.adaptive.added_findings} additional findings · ${esc(human(result.adaptive.stop_reason))}</p>`:''}
    ${result.adaptive?.unresolved_questions?.length?`<details class="routine"><summary>Questions still needing evidence</summary><ul>${result.adaptive.unresolved_questions.map((g,index)=>`<li>${esc(g.question||g.topic?.replaceAll('_',' ')||'Additional source evidence is needed')} <button class="text-button" data-action="research-followup" data-index="${index}">Explore this question ↗</button></li>`).join('')}</ul></details>`:''}
    ${result.coverage?`<p class="help">Focused review · AI reviewed evidence from ${result.coverage.reviewed_pages??result.coverage.selected_pages} pages · ${result.coverage.indexed_pages} pages indexed · ${result.elapsed_seconds}s this attempt${result.wall_elapsed_seconds!==undefined?' · '+result.wall_elapsed_seconds+'s since queued':''}</p>`:''}
${sourceCoverage(job)}${documents(docs,focused)}<p class="help">Models: ${esc(result.models_used?.join(' · ')||'Not recorded')}<br>Sources collected ${when(job.data_as_of?.collected_at,true)} IST. Source publication periods may be earlier.</p></details></div></section>`;}
  const failed=job.status==='failed'||unavailable,retry=job.status==='waiting'&&job.next_attempt_at;
  const message=quotaPaused?quotaMessage:retry?`The backend will pick this up automatically on an available research turn after ${when(job.next_attempt_at,true)} IST. Keep the backend running. You can close this tab.`:
    failed?'Check the error details before retrying. Saved page reviews will be reused.':'All document text is indexed locally. The AI reviews selected evidence relevant to your question and saves a cited brief.';
  return `<section class="panel research-loading"><div class="loading-orb ${failed?'paused':''}" aria-hidden="true">${failed?'Ⅱ':'✧'}</div><h2>${failed?'Research needs your attention':'Building your company view'}</h2><p>${esc(job.nse_symbol)} · ${failed?'Your saved progress is retained.':'Reading primary sources and connecting the evidence.'}</p>${!failed?'<div class="skeleton-preview" aria-hidden="true"><span></span><span></span><span></span></div>':''}${failed?`<p class="help">${esc(message)}</p><button class="button secondary" data-action="retry-research" data-id="${esc(job.id)}">Retry research</button>`:''}<details class="research-progress"><summary>Research progress & source details</summary><p>${esc(job.progress||'Waiting for sources')}</p><p>${esc(message)}</p>${job.error?`<p class="error-details">${esc(job.error)}</p>`:''}${sourceCoverage(job)}${documents(docs,focused)}</details></section>`;

}
function sourceCoverage(job){
  const sources=job.sources||[];if(!sources.length)return '';
  const chosen=sources.filter(s=>s.download_status),deferred=sources.filter(s=>!s.download_status);
  return `<p class="help">${sources.length} source links discovered · ${chosen.length} documents selected · ${sources.filter(s=>s.download_status==='downloaded').length} downloaded. ${job.options?.source_policy==='assignment'?'Annual reports and transcripts only.':'Additional company disclosures may supplement annual reports and transcripts.'}</p>
    ${deferred.length?`<details class="routine"><summary>Other available sources (${deferred.length})</summary><p class="help">These links were discovered but have not been downloaded or reviewed. Further research may use them to answer unresolved questions.</p><ul>${deferred.map(s=>`<li>${sourceLink(s.source_url,s.title)}${s.metadata?.period_label?' · '+esc(s.metadata.period_label):''}</li>`).join('')}</ul></details>`:''}`;
}
function documents(docs=[],focused=false){
  return `<div style="margin-top:18px">${docs.map(d=>{
    const total=Number(d.total_pages??d.extraction_metadata?.totalPages)||0;
    const prepared=Number(d.prepared_pages??d.extraction_metadata?.pagesPrepared)||0;
    const progress=(label,count,denominator=total)=>`<p>${label} · ${number(count)} / ${number(denominator)} pages (${Math.floor(count/denominator*100)}%)</p><div class="progress-track" role="progressbar" aria-label="${label} for ${esc(d.title)}" aria-valuenow="${count}" aria-valuemin="0" aria-valuemax="${denominator}"><span style="width:${Math.min(100,count/denominator*100)}%"></span></div>`;
    return `<div class="document"><div class="document-head">${sourceLink(d.metadata?.primary_url||d.source_url,d.title+' ↗')}<span class="cell-sub">${esc(human(d.kind))}</span></div>
      ${d.metadata?.period_label||d.metadata?.published_at?`<p class="help">${esc(d.metadata.period_label||'Issuer disclosure')}${d.metadata?.published_at?' · Published '+when(d.metadata.published_at):''}</p>`:''}${d.metadata?.selection_reason?`<p class="help">${esc(d.metadata.selection_reason)}</p>`:''}
      ${total?progress(focused?'Text pages indexed':'PDF pages prepared',prepared):badge(d.status==='failed'?'failed':d.extraction_status||d.status)}
      ${total?(Number.isInteger(d.reviewed_pages)?(focused?(d.selected_pages?.length?progress('AI review saved for selected pages',Math.min(d.reviewed_pages,d.selected_pages.length),d.selected_pages.length):'<p class="help">Selecting evidence for your question…</p>'):progress('AI review saved',d.reviewed_pages)):'<p class="help">Restart the local backend to enable AI review counts for this job.</p>'):''}
      ${d.error?`<p class="negative">${esc(d.error)}</p>`:''}</div>`;
  }).join('')}</div>`;
}

function modal(title,content,footer=''){modalVersion++; $('#modal-body').innerHTML=`<div class="modal-header"><h2 id="modal-title">${esc(title)}</h2><button class="icon-button" data-action="close-modal" aria-label="Close dialog">×</button></div><div class="modal-content">${content}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}`;if(!$('#modal').open)$('#modal').showModal();}
function openSettings(){const s=state.settings;if(!s)return toast('Settings have not loaded yet.',true);const r=type=>s.rules.find(r=>r.rule_type===type);const checked=value=>value?'checked':'';
  modal('Watcher settings',`<form id="settings-form"><div class="toggle-row"><label class="check"><input type="checkbox" name="monitoring_enabled" ${checked(s.monitoring_enabled)}> Enable routine monitoring</label></div><div class="settings-grid"><div><label for="monitor-minutes">Check interval · minutes</label><input id="monitor-minutes" type="number" name="monitoring_minutes" min="1" max="1440" required value="${s.monitoring_minutes}"></div><div><label for="digest-hours">Digest window · hours</label><input id="digest-hours" type="number" name="digest_hours" min="1" max="168" required value="${s.digest_hours}"></div></div>
    <div class="settings-section"><h3>Unusual market activity</h3><div class="settings-grid"><div><label class="check"><input type="checkbox" name="price_enabled" ${checked(r('price_move')?.enabled)}> Daily price alerts</label><label for="price-percent">Move beyond ± %</label><input id="price-percent" type="number" name="price_percent" min="0.01" step="any" max="1000" required value="${r('price_move')?.settings.percent??5}"></div><div><label class="check"><input type="checkbox" name="volume_enabled" ${checked(r('volume_spike')?.enabled)}> Volume alerts</label><label for="volume-multiple">Multiple of average</label><input id="volume-multiple" type="number" name="volume_multiple" min="0.01" step="any" max="1000" required value="${r('volume_spike')?.settings.multiple??2}"></div><div><label for="volume-sessions">Prior sessions for volume average</label><input id="volume-sessions" type="number" name="volume_sessions" min="2" max="250" required value="${r('volume_spike')?.settings.sessions??20}"></div></div><p class="help">These rules use completed daily sessions. Enough historical data is needed to calculate a baseline.</p></div>
    <div class="settings-section"><h3>Important announcements</h3><label class="check"><input type="checkbox" name="announcement_enabled" ${checked(r('announcement')?.enabled)}> Alert on material announcements in selected categories</label><div class="category-grid" style="margin-top:18px">${categories.map(c=>`<label class="check"><input type="checkbox" name="category" value="${esc(c)}" ${checked(r('announcement')?.settings.categories.includes(c))}> ${esc(human(c))}</label>`).join('')}</div></div><p class="help" style="margin-top:20px">Changing the digest window starts a new schedule. Already collected data is kept.</p><p id="settings-error" class="form-error" role="alert" hidden></p></form>`,
    '<button class="text-button" data-action="status">Backend activity & retries</button><button class="button secondary" data-action="close-modal">Cancel</button><button class="button primary" type="submit" form="settings-form">Save preferences</button>');
}
function evidenceDialog(evidence,title='Source evidence'){
  const rows=Array.isArray(evidence)?evidence:[evidence];
  modal(title,rows.length?rows.map(e=>`<section class="report-section"><div class="feed-meta"><span>${esc(e.source_title||'Primary source')}</span>${e.page||e.location?.page?`<span>Page ${number(e.page||e.location.page)}</span>`:''}<span>${esc(e.modality||e.evidence_snapshot?.modality||'text')} evidence</span></div><blockquote class="evidence-quote">${esc(e.quote||e.evidence_snapshot?.quote||'No quotation retained.')}</blockquote>${sourceLink(e.source_url,'Open original document ↗')}${e.id&&(e.has_image||e.modality==='visual')?`<details class="routine"><summary>View cited page image</summary><img class="evidence-image" loading="lazy" src="/api/app?resource=evidence&amp;id=${encodeURIComponent(e.id)}" alt="Cited page ${esc(e.page||e.location?.page||'')} from the source document"></details>`:''}</section>`).join(''):'<p class="muted">No retained evidence is available.</p>');
}
async function companyDialog(symbol){modal(symbol,'<div class="loading-line"><span class="spinner"></span> Loading company history…</div>');
  const version=modalVersion,company=await api('company',{params:{symbol}});if(!$('#modal').open||version!==modalVersion)return;
  const closes=company.observations.filter(o=>o.metric==='close'&&o.scope==='market'&&o.frequency==='daily').sort((a,b)=>+new Date(a.period_end)-+new Date(b.period_end));
  const current=state.portfolio.find(c=>c.nse_symbol===symbol)?.market;
  modal(symbol,`<div class="detail-stats">${stat('Latest EOD close',money(current?.close),current?when(current.session_date):'No saved session')}${stat('Daily change',percent(current?.change_percent),'Versus prior saved session')}${stat('Volume',compact(current?.volume),'Shares traded')}</div>
    <h3>Recent closing prices</h3>${closes.length>1?chart(closes):'<p class="muted">At least two completed sessions are needed to display a chart.</p>'}
    <p class="help">Saved daily closes, not live quotes. ${sourceLink(current?.source_url,'Price source ↗')}</p><div class="settings-section"><h3>Saved company developments</h3>${company.events.length?company.events.map(e=>`<article class="company-event"><div class="feed-meta">${badge(e.importance)}<span>${when(e.updated_at,true)} IST</span></div><h3>${esc(e.title)}</h3><p class="muted">${esc(e.summary)}</p><button class="text-button" data-action="company-evidence" data-event="${esc(e.id)}" data-symbol="${esc(symbol)}">Read source evidence ↗</button></article>`).join(''):'<p class="muted">No analysed developments saved yet.</p>'}</div>`,
    `<button class="button secondary" data-action="research-company" data-symbol="${esc(symbol)}">Research ${esc(symbol)} ↗</button><button class="button secondary" data-action="close-modal">Close</button>`);
}
function chart(rows){const values=rows.map(r=>Number(r.value)),low=Math.min(...values),high=Math.max(...values),range=high-low||1;
  const points=values.map((v,i)=>`${20+i/(values.length-1)*540},${150-(v-low)/range*125}`).join(' ');
  return `<svg class="chart" viewBox="0 0 580 180" role="img" aria-label="${rows.length} saved closing prices, from ${esc(money(values[0]))} to ${esc(money(values.at(-1)))}"><path d="M20 150H560M20 85H560M20 25H560" stroke="#edf0e6" fill="none"/><polygon points="20,160 ${points} 560,160" fill="#eef4e6"/><polyline points="${points}" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><text x="20" y="15" fill="#99a58c" font-size="10">${esc(money(high))}</text><text x="20" y="178" fill="#99a58c" font-size="10">${esc(money(low))}</text></svg><div class="chart-label"><span>${when(rows[0].period_end)}</span><span>${when(rows.at(-1).period_end)}</span></div>`;
}
function statusDialog(){const s=state.status;if(!s)return toast('Processing status is unavailable.',true);
  modal('Backend activity',`<div class="notice neutral">${esc(s.scheduler_note)}${s.deployment_commit?` Build ${esc(s.deployment_commit)}.`:''} Data-source or model outages can delay updates; progress is saved.</div><h3>Document processing</h3>${s.jobs?.length?`<div class="table-wrap"><table><thead><tr><th>STAGE</th><th>STATUS</th><th>JOBS</th></tr></thead><tbody>${s.jobs.map(j=>`<tr><td>${j.job_type==='extract'?'Prepare pages':'Analyse filings'}</td><td>${badge(j.status)}</td><td>${number(j.count)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No document jobs yet.</p>'}<div class="settings-section"><h3>Last background step</h3><p class="muted">${esc(human(s.monitor?.last_result?.phase||'Not started'))} · ${when(s.monitor?.last_finished_at,true)} IST</p>${s.monitor?.last_error?`<p class="error-details">${esc(s.monitor.last_error)}</p>`:''}</div>
  ${s.collection?.some(c=>c.last_error)?`<div class="settings-section"><h3>Collection errors</h3>${s.collection.filter(c=>c.last_error).map(c=>`<details class="routine"><summary>${esc(c.nse_symbol)} · ${c.source==='yahoo'?'Prices':'Announcements'} · ${when(c.last_attempt_at,true)} IST</summary><p class="error-details">${esc(c.last_error)}</p></details>`).join('')}</div>`:''}
  ${s.processingErrors?.length?`<div class="settings-section"><h3>Recent processing errors</h3>${s.processingErrors.map(e=>`<details class="routine"><summary>${esc(human(e.job_type))} · ${esc(human(e.error_kind||e.status))}${e.next_attempt_at?` · next retry ${when(e.next_attempt_at,true)} IST`:''}</summary><p class="error-details">${esc(e.error)}</p>${e.quota_retry_at?`<p class="help">Request limit reached. Retry after ${when(e.quota_retry_at,true)} IST; no automatic retry.</p>`:''}${e.job_type==='analyse'&&e.status==='failed'?`<button class="button secondary compact" data-action="retry-analysis" data-id="${esc(e.id)}">Retry analysis</button>`:''}</details>`).join('')}</div>`:''}`);
}

$('#login-form').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button');button.disabled=true;$('#auth-error').hidden=true;
  try{await api('session',{method:'POST',body:{access_code:$('#access-code').value}});$('#access-code').value='';await enterWorkspace();}
  catch(error){$('#auth-error').textContent=error.message;$('#auth-error').hidden=false;}finally{button.disabled=false;}});
$('#connection-retry').addEventListener('click',checkSession);
document.addEventListener('submit',async event=>{
  const form=event.target;if(!['add-company','research-form','settings-form'].includes(form.id))return;event.preventDefault();
  const data=new FormData(form),button=form.querySelector('[type="submit"]')||document.querySelector(`[form="${form.id}"]`);if(button)button.disabled=true;
  try{
    if(form.id==='add-company'){await api('portfolio',{method:'POST',body:{symbol:researchSymbol(String(data.get('symbol')))}});state.tickerDraft='';toast('Company added. Its first collection has been queued.');await load({force:true});}
    if(form.id==='research-form'){
      state.starting=true;paint(true);const result=await api('research',{method:'POST',body:{symbol:researchSymbol(String(data.get('symbol'))),question:String(data.get('question')||'').trim(),source_policy:String(data.get('source_policy')||'primary')}});
      state.starting=false;toast('Research queued. Follow its progress here.');location.hash=`research/${result.id}`;readRoute();await load({force:true});
    }
    if(form.id==='settings-form'){
      const patch={};for(const name of ['monitoring_minutes','digest_hours','price_percent','volume_multiple','volume_sessions'])patch[name]=Number(data.get(name));
      for(const name of ['monitoring_enabled','price_enabled','volume_enabled','announcement_enabled'])patch[name]=data.has(name);
      patch.announcement_categories=data.getAll('category');await api('settings',{method:'PATCH',body:patch});$('#modal').close();toast('Watcher preferences saved.');await load({force:true});
    }
  }catch(error){if(form.id==='settings-form'){$('#settings-error').textContent=error.message;$('#settings-error').hidden=false;}else toast(error.message,true);}
  finally{state.starting=false;if(button?.isConnected)button.disabled=false;}
});
document.addEventListener('input',event=>{const e=event.target;if(e.id==='research-symbol')$('#company-suggestions').innerHTML=companyOptions(e.value);if(e.id==='ticker'){state.tickerDraft=e.value;$('#portfolio-suggestions').innerHTML=companyOptions(e.value);}if(e.closest('#research-form')&&e.name)state.draft[e.name]=e.value;});
document.addEventListener('change',async event=>{const e=event.target;if(e.id==='market-session'){const data=researchMarkets.get(state.job?.nse_symbol)?.data,r=data?.rows[Number(e.value)];if(r)$('#market-point-detail').textContent=`${r.day} · Close ${money(r.values.close)} · High ${money(r.values.high)} · Low ${money(r.values.low)} · Volume ${number(r.values.volume)}`;}if(e.closest('#research-form')&&e.name)state.draft[e.name]=e.value;if(e.id==='digest-window'){state.window=Number(e.value);state.selectedDigest=null;await load({force:true});}});
document.addEventListener('click',async event=>{
  if(event.target.closest('.skip-link')){event.preventDefault();$('#main').focus();return;}
  const button=event.target.closest('[data-action]');if(!button)return;const action=button.dataset.action;
  try{
    if(action==='alert-filter'){alertFilter=button.dataset.filter;paint(true);return;}
    if(action==='theme-toggle'){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';applyTheme(next);try{localStorage.setItem('finn-theme',next);}catch{}return;}
    if(action==='close-modal'){$('#modal').close();return;}
    if(action==='settings'){openSettings();return;}
    if(action==='status'){statusDialog();return;}
    if(action==='company'){await companyDialog(button.dataset.symbol);return;}
    if(action==='research-add-portfolio'){button.disabled=true;await api('portfolio',{method:'POST',body:{symbol:button.dataset.symbol}});toast('Company added to your portfolio.');await load({force:true});return;}
    if(action==='market-retry'){researchMarkets.delete(button.dataset.symbol);await loadResearchMarket(button.dataset.symbol);return;}
    if(action==='market-range'){researchRange=button.dataset.range;paint(true);return;}
    if(action==='market-table'){researchMarketTable=!researchMarketTable;paint(true);return;}
    if(action==='market-point'){const data=researchMarkets.get(state.job?.nse_symbol)?.data,row=data?.rows[Number(button.dataset.index)];if(row){$('#market-point-detail').textContent=`${row.day} · Close ${money(row.values.close)} · Volume ${number(row.values.volume)} · High ${money(row.values.high)} · Low ${money(row.values.low)}`;}return;}
    if(action==='exhibit-toggle'){const table=$('#research-table'),charts=$('#research-charts');table.hidden=!table.hidden;charts.hidden=!charts.hidden;return;}
    if(action==='report-section'){event.preventDefault();const section=document.getElementById('section-'+button.dataset.topic);if(section){section.open=true;section.scrollIntoView({behavior:'smooth',block:'start'});}return;}
    if(action==='observation'){
      const o=state.job?.result?.exhibits?.observations?.[Number(button.dataset.index)];if(!o)return;
      modal(o.label||human(o.metric),`<p><strong>${number(o.value)} ${esc(o.unit)}</strong> · ${esc(o.scope)}</p><p>${esc(o.period_start)} → ${esc(o.period_end)}</p><p>Definition: ${esc(human(o.metric))}. Value transcribed from the source; no calculated transformation.</p><blockquote>${esc(o.quote)}</blockquote><p>${sourceLink(o.source_url,o.source_title+' · page '+o.page)}</p>`,`<button class="button secondary" data-action="close-modal">Close</button>`);return;
    }
    if(action==='research-followup'){
      const gap=state.job?.result?.adaptive?.unresolved_questions?.[Number(button.dataset.index)];
      if(gap){state.draft={symbol:state.job.nse_symbol,question:gap.question,source_policy:state.job.options?.source_policy||'primary'};paint(true);$('#research-question')?.focus();$('#research-form')?.scrollIntoView({block:'start',behavior:'smooth'});}
      return;
    }
    if(action==='research-company'){$('#modal').close();state.draft.symbol=button.dataset.symbol;location.hash='research';paint(true);return;}
    if(action==='delete-research'){
      const job=state.research.find(j=>j.id===button.dataset.id)||(state.job?.id===button.dataset.id?state.job:null);if(!job)return;
      modal('Delete this research?',`<p><strong>${esc(job.nse_symbol)}</strong> · ${when(job.created_at,true)} IST</p><p>${esc(job.question)}</p><p>This permanently removes the report, citations and saved progress for this job.${['queued','running','waiting'].includes(job.status)?' It also stops this research job.':''} Source documents remain cached for reuse.</p>`,
        `<button class="button secondary" data-action="close-modal">Cancel</button><button class="button danger" data-action="confirm-delete-research" data-id="${esc(job.id)}">Delete research</button>`);
      return;
    }
    if(action==='research-job'){location.hash=`research/${button.dataset.id}`;return;}
    if(action==='preset'){const prompts={business:'Explain the business, its main segments, and what is driving growth. Ground the overview in the annual report and transcript.',cash:'Do the reported profits turn into cash? Explain cash from operations, debt, working capital, and any explicit concerns in the primary sources.',guidance:'What has management explicitly guided for growth, margins, or capital expenditure? Compare promises with reported outcomes where the selected sources support it, and identify missing periods.'};state.draft.question=prompts[button.dataset.preset];$('#research-question').value=state.draft.question;$('#research-question').focus();return;}
    if(action==='saved-digest'){state.selectedDigest=state.digests.find(d=>d.id===button.dataset.id);paint(true);window.scrollTo({top:0,behavior:'smooth'});return;}
    if(action==='current-digest'){state.selectedDigest=null;paint(true);return;}
    if(action==='research-evidence'){const index=Number(button.dataset.index);evidenceDialog((state.job?.result?.evidence||[]).filter(e=>e.fact_index===index),`Research source [${index+1}]`);return;}
    if(action==='digest-evidence'){const digest=state.selectedDigest?.result||state.digest,item=digest?.items.find(i=>i.id===button.dataset.disclosure),development=item?.developments?.[Number(button.dataset.index)];evidenceDialog(development?.evidence||[]);return;}
    if(action==='company-evidence'){const details=await api('company',{params:{symbol:button.dataset.symbol}});evidenceDialog(details.evidence.filter(e=>e.event_id===button.dataset.event).map(e=>({...e,...e.evidence_snapshot})));return;}
    if(action==='remove'){modal('Stop watching this company?',`<p>Remove <strong>${esc(button.dataset.symbol)}</strong> from your watchlist? Previously collected data and research will be kept.</p>`,`<button class="button secondary" data-action="close-modal">Keep watching</button><button class="button danger" data-action="confirm-remove" data-symbol="${esc(button.dataset.symbol)}">Stop watching</button>`);return;}
    button.disabled=true;
    if(action==='confirm-delete-research'){
      const id=button.dataset.id;await api('research',{method:'DELETE',body:{id}});
      deletedResearch.add(id);state.research=state.research.filter(job=>job.id!==id);
      if(state.selectedJob===id){state.job=null;history.replaceState(null,'','#research');readRoute();}
      $('#modal').close();paint(true);toast('Research deleted.');await load({force:true});return;
    }
    if(action==='confirm-remove'){await api('portfolio',{method:'DELETE',body:{symbol:button.dataset.symbol}});$('#modal').close();toast('Company removed from the watchlist.');await load({force:true});}
    if(action==='logout'){await api('session',{method:'DELETE'});state.portfolio=null;state.job=null;state.draft={symbol:'',question:'',source_policy:'primary'};showLogin();}
    if(action==='generate-digest'){const saved=await api('digest',{method:'POST',body:{}});state.selectedDigest=saved;toast('Digest saved. Pending collection and analysis are labelled.');await load({force:true});}
    if(action==='refresh'){state.refreshing=true;await api('refresh',{method:'POST'});state.refreshing=false;toast('Refresh queued. Keep the app open while prices and updates are collected.');await load({force:true});}
    if(action==='retry-analysis'){await api('analysis-retry',{method:'POST',body:{id:button.dataset.id}});$('#modal').close();toast('Analysis queued; saved batches will be reused.');await load({force:true});return;}
    if(action==='toggle-monitor'){await api('settings',{method:'PATCH',body:{monitoring_enabled:!state.settings.monitoring_enabled}});toast(state.settings.monitoring_enabled?'Monitoring paused. Saved data is kept.':'Monitoring resumed.');await load({force:true});}
    if(action==='read-notification'){await api('notifications',{method:'PATCH',body:{id:button.dataset.id}});await load({force:true});}
    if(action==='retry-research'){await api('research-retry',{method:'POST',body:{id:button.dataset.id}});toast('Research requeued. Saved successful batches will be reused.');await load({force:true});}
  }catch(error){toast(error.message,true);}finally{state.refreshing=false;if(button.isConnected)button.disabled=false;}
});
